package com.way2jobs.notification.controller;
import com.way2jobs.notification.dto.NotificationResponse; import com.way2jobs.notification.service.NotificationService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.Map;
@RestController @RequestMapping("/api/notifications") @RequiredArgsConstructor public class NotificationController {private final NotificationService service; @GetMapping public Page<NotificationResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.getNotifications(page,size);}@GetMapping("/unread-count") public Map<String,Long> unread(@RequestParam(required=false)LocalDateTime since){return Map.of("count",service.unreadCount(since==null?LocalDateTime.now().minusDays(7):since));}}
